{
  "documentKind": "bounded-independent-redteam-recommendation/1",
  "role": "redteam",
  "questionId": "Q-U07",
  "scopeStatus": "COMPLETE",
  "scopeMeaning": "Vollstaendige adversarielle Empfehlung ausschliesslich zu Q1-Q6; keine Annahme des Profils und kein geschlossenes Gesamtoracle",
  "wholeRoleStatus": "INCOMPLETE_OTHER_QUESTIONS_PENDING",
  "wholeManifestVerdict": "NOT_ISSUED",
  "recommendation": {
    "id": "EVENT_BOUND_PROSPECTIVE_QUALIFICATION_WITH_PROFILE_CORRECTION",
    "normativeQualificationProposal": "Eine fehlende Sequenznummer begrenzt nicht die Zahl unbeobachteter Weltaktionen. U07 begruendet deshalb ohne zusaetzliche geschlossene Beobachtungsannahme keinen zwingenden Undo-Konflikt. Konsistente Moeglichkeiten ersetzen keine beobachtete Geschichte und keinen Materialbeweis. Bereits gueltig beobachtete Hilfe bleibt erhalten; spezifische Zielhilfe und Hilfefreiheit benoetigen eigene Belege. Eine frische gueltige direkte Antwort nach der Luecke bleibt unabhaengig anerkennbar. Alte Inputs, Sollfehler, Rohabweichungen und INCONCLUSIVE-Qualifikation werden nicht veraendert.",
    "adoptionStatus": "PROPOSED_NOT_ACCEPTED",
    "unconditionalAcceptance": false,
    "rejectBlanketGap15Approval": true,
    "meaning": "Keine harte U07-Undosperre aus einer Ein-Slot-Hypothese; App-Hilfe positiv erhalten; Ergebnis eigenstaendig anerkennen; unbekanntes Material nicht erfinden."
  },
  "normativeClassification": "ALREADY_DECIDED_TECHNICAL_DERIVATION",
  "normativeClassificationBoundary": {
    "included": [
      "Keine Weltaktionsobergrenze aus seq",
      "Konsistente Moeglichkeit ist kein beobachteter Weltverlauf",
      "Erhalt gueltig beobachteter App-Hilfe",
      "Frische direkte Antwort bleibt enger Nachweis",
      "Unveraenderte historische Rohfehler und Qualifikation"
    ],
    "excluded": [
      "Neue Coverage-Prioritaetsregel bei fehlendem Zielanker",
      "Allgemeine proof.*.valid-Totalisierung",
      "Annahme aller Reportfelder oder aller Faelle",
      "Neue Produktpraeferenz oder Ratifikation"
    ],
    "authority": [
      "ADR0003 D1.1,D1.6,D1.7,D2.3,D2.5-D2.8,D5,D6",
      "CONTRACT.md lines 31-41,53-65"
    ],
    "missingEvidenceCannotBeVotedAway": true
  },
  "sectionAssessments": {
    "Q1": {
      "status": "COMPLETE",
      "assessment": "Alte Sollfehler, dokumentierte Roh-FAILs und INCONCLUSIVE als harter Befund getrennt; kein neues altes PASS."
    },
    "Q2": {
      "status": "COMPLETE",
      "assessment": "Echte Move-/Undo-/Item-/Actoridentitaeten gebunden; unbeschraenkte Luecke; U07 ohne spaeteres Undo B/C, N20 mit zwingendem Widerspruch, N26 als Textgrenze."
    },
    "Q3": {
      "status": "COMPLETE",
      "assessment": "Material, Provenienz, Historie, allgemeine und spezifische Hilfe sowie direkte Antwort getrennt. App support.general=wahr; Kind unbekannt."
    },
    "Q4": {
      "status": "COMPLETE",
      "assessment": "Je Fall alle betroffenen Fakten und Claims als manuelle Vorschlaege oder ausdruecklich offene Abhaengigkeiten; keine Gueltigkeits-Totalisierung."
    },
    "Q5": {
      "status": "COMPLETE",
      "assessment": "Enger Qualifikationsabsatz als technische Ableitung; revisionsgebundener Alt-Neu-Eintrag erforderlich; Kontrollen nur dokumentarisch."
    },
    "Q6": {
      "status": "COMPLETE",
      "assessment": "Beratung Q1-Q6 vollstaendig; technische Folgearbeit und fremde Annahme offen; kein Schliessen durch diese Rolle."
    }
  },
  "conditions": [
    {
      "id": "C-INTEGRITY",
      "text": "Fachliche Vorschlaege gelten nur bei gesondert gesicherter Struktur-, Referenz-, Kandidaten- und Kontextbindung. Ein echter Integritaetsfehler erlaubt keinen Teilreport. Hier keine entsprechende Software ausgefuehrt."
    },
    {
      "id": "C-HELP",
      "text": "App support.general muss aus seq 1-3 wahr bleiben; keine Erfindung spezifischer Zielhilfe und kein falscher Hilfefreiheitsbeleg aus leeren Signalzeilen."
    },
    {
      "id": "C-COVERAGE",
      "text": "support.coverage.ten/doubles fallweise an Zielanker binden; Katalogabgrenzung falsch bei nachgewiesener Luecke gegen unbekannt ohne Anker explizit klaeren, nicht generisches gap15 bestaetigen."
    },
    {
      "id": "C-GUARD",
      "text": "Q-GUARD-TOTALISATION bleibt separat. Vorgeschlagene undecidable-Claims setzen voraus, dass kein gesonderter gueltiger Guardveto entsteht; bei Veto must_not_claim. Kein proof.* pauschal wahr."
    },
    {
      "id": "C-REVISION",
      "text": "Alte Originaldateien, Kandidaten, Sollwerte, Rohabweichungen und INCONCLUSIVE behalten; nur neue explizite Revision/Bindings/Erwartungsdifferenz."
    },
    {
      "id": "C-REVIEW",
      "text": "Weitere Rollen und Elternpruefung muessen ihre eigenen vollstaendigen Empfehlungen abgeben. Diese Rolle vertritt sie nicht. Keine Mehrheit behauptet."
    },
    {
      "id": "C-GATE",
      "text": "Neue ganze Manifestfassung, Freeze und Fremdpruefung bleiben vor Implementation zwingend; enge Digestannahme aendert diese Sperre nicht."
    }
  ],
  "remainingGaps": [
